)

layerPlotResults <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "layerPlotResults",
    inherit = jmvcore::Group,
    active = list(
        messages = function() private$.items[["messages"]],
        plot = function() private$.items[["plot"]],
        code = function() private$.items[["code"]]),
    private = list(),
    public=list(
        initialize=function(options) {
            super$initialize(
                options=options,
                name="",
                title="Layered ggplot",
                refs=list(
                    "ggplot2"))
            self$add(jmvcore::Preformatted$new(
                options=options,
                name="messages",
                title="Messages",
                visible=FALSE))
            self$add(jmvcore::Image$new(
                options=options,
                name="plot",
                title="Plot",
                width=600,
                height=450,
                renderFun=".plot"))
            self$add(jmvcore::Preformatted$new(
                options=options,
                name="code",
                title="Equivalent R code",
                visible="(showCode)"))}))

layerPlotBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "layerPlotBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "jmvggplot",
                name = "layerPlot",
                version = c(0,0,1),
                options = options,
                results = layerPlotResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Layered ggplot
#'
#' Builds a ggplot2 plot from an ordered list of layers and shows the 
