#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$code} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
layerPlot <- function(
    data,
    x = NULL,
    y = NULL,
    colour = NULL,
    fill = NULL,
    shape = NULL,
    sizeBy = NULL,
    alphaBy = NULL,
    group = NULL,
    label = NULL,
    ymin = NULL,
    ymax = NULL,
    xend = NULL,
    yend = NULL,
    facetVar1 = NULL,
    facetVar2 = NULL,
    addLayer = "none",
    facetType = "none",
    facetScales = "fixed",
    facetCols = 0,
    act1 = "none",
    l1_type = "point",
    l1_enabled = TRUE,
    l1_inherit = TRUE,
    l1_alpha = 1,
    l1_size = 0,
    l1_width = 0,
    l1_position = "default",
    l1_stat = "mean_se",
    l1_method = "lm",
    l1_se = TRUE,
    l1_bins = 30,
    l1_intercept = 0,
    l1_slope = 1,
    act2 = "none",
    l2_type = "none",
    l2_enabled = TRUE,
    l2_inherit = TRUE,
    l2_alpha = 1,
    l2_size = 0,
    l2_width = 0,
    l2_position = "default",
    l2_stat = "mean_se",
    l2_method = "lm",
    l2_se = TRUE,
    l2_bins = 30,
    l2_intercept = 0,
    l2_slope = 1,
    act3 = "none",
    l3_type = "none",
    l3_enabled = TRUE,
    l3_inherit = TRUE,
    l3_alpha = 1,
    l3_size = 0,
    l3_width = 0,
    l3_position = "default",
    l3_stat = "mean_se",
    l3_method = "lm",
    l3_se = TRUE,
    l3_bins = 30,
    l3_intercept = 0,
    l3_slope = 1,
    act4 = "none",
    l4_type = "none",
    l4_enabled = TRUE,
    l4_inherit = TRUE,
    l4_alpha = 1,
    l4_size = 0,
    l4_width = 0,
    l4_position = "default",
    l4_stat = "mean_se",
    l4_method = "lm",
    l4_se = TRUE,
    l4_bins = 30,
    l4_intercept = 0,
    l4_slope = 1,
    act5 = "none",
    l5_type = "none",
    l5_enabled = TRUE,
    l5_inherit = TRUE,
    l5_alpha = 1,
    l5_size = 0,
    l5_width = 0,
    l5_position = "default",
    l5_stat = "mean_se",
    l5_method = "lm",
    l5_se = TRUE,
    l5_bins = 30,
    l5_intercept = 0,
    l5_slope = 1,
    act6 = "none",
    l6_type = "none",
