    l6_bins = 30,
    l6_intercept = 0,
    l6_slope = 1,
    xTrans = "identity",
    yTrans = "identity",
    xMin = "",
    xMax = "",
    yMin = "",
    yMax = "",
    rangeMode = "zoom",
    coordType = "cartesian",
    colourPalette = "default",
    colourValues = "",
    fillPalette = "default",
    fillValues = "",
    legendPosition = "right",
    colourTitle = "",
    fillTitle = "",
    shapeTitle = "",
    sizeTitle = "",
    alphaTitle = "",
    title = "",
    subtitle = "",
    caption = "",
    xlab = "",
    ylab = "",
    baseSize = 11,
    baseFamily = "default",
    hideGridMajor = FALSE,
    hideGridMinor = FALSE,
    hideTicks = FALSE,
    boldTitle = FALSE,
    xTextAngle = "default",
    plotFill = "",
    panelFill = "",
    plotMargin = "",
    theme = "minimal",
    showCode = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("layerPlot requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if ( ! missing(y)) y <- jmvcore::resolveQuo(jmvcore::enquo(y))
    if ( ! missing(colour)) colour <- jmvcore::resolveQuo(jmvcore::enquo(colour))
    if ( ! missing(fill)) fill <- jmvcore::resolveQuo(jmvcore::enquo(fill))
    if ( ! missing(shape)) shape <- jmvcore::resolveQuo(jmvcore::enquo(shape))
    if ( ! missing(sizeBy)) sizeBy <- jmvcore::resolveQuo(jmvcore::enquo(sizeBy))
    if ( ! missing(alphaBy)) alphaBy <- jmvcore::resolveQuo(jmvcore::enquo(alphaBy))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(label)) label <- jmvcore::resolveQuo(jmvcore::enquo(label))
    if ( ! missing(ymin)) ymin <- jmvcore::resolveQuo(jmvcore::enquo(ymin))
    if ( ! missing(ymax)) ymax <- jmvcore::resolveQuo(jmvcore::enquo(ymax))
    if ( ! missing(xend)) xend <- jmvcore::resolveQuo(jmvcore::enquo(xend))
    if ( ! missing(yend)) yend <- jmvcore::resolveQuo(jmvcore::enquo(yend))
    if ( ! missing(facetVar1)) facetVar1 <- jmvcore::resolveQuo(jmvcore::enquo(facetVar1))
    if ( ! missing(facetVar2)) facetVar2 <- jmvcore::resolveQuo(jmvcore::enquo(facetVar2))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL),
            `if`( ! missing(y), y, NULL),
            `if`( ! missing(colour), colour, NULL),
            `if`( ! missing(fill), fill, NULL),
            `if`( ! missing(shape), shape, NULL),
            `if`( ! missing(sizeBy), sizeBy, NULL),
            `if`( ! missing(alphaBy), alphaBy, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(label), label, NULL),
            `if`( ! missing(ymin), ymin, NULL),
            `if`( ! missing(ymax), ymax, NULL),
            `if`( ! missing(xend), xend, NULL),
            `if`( ! missing(yend), yend, NULL),
            `if`( ! missing(facetVar1), facetVar1, NULL),
            `if`( ! missing(facetVar2), facetVar2, NULL))

    for (v in shape) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in facetVar1) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in facetVar2) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- layerPlotOptions$new(
        x = x,
        y = y,
        colour = colour,
        fill = fill,
        shape = shape,
        sizeBy = sizeBy,
        alphaBy = alphaBy,
        group = group,
        label = label,
        ymin = ymin,
        ymax = ymax,
        xend = xend,
        yend = yend,
        facetVar1 = facetVar1,
        facetVar2 = facetVar2,
        addLayer = addLayer,
        facetType = facetType,
        facetScales = facetScales,
        facetCols = facetCols,
        act1 = act1,
        l1_type = l1_type,
        l1_enabled = l1_enabled,
        l1_inherit = l1_inherit,
        l1_alpha = l1_alpha,
        l1_size = l1_size,
        l1_width = l1_width,
        l1_position = l1_position,
        l1_stat = l1_stat,
        l1_method = l1_method,
        l1_se = l1_se,
        l1_bins = l1_bins,
        l1_intercept = l1_intercept,
        l1_slope = l1_slope,
        act2 = act2,
        l2_type = l2_type,
        l2_enabled = l2_enabled,
        l2_inherit = l2_inherit,
        l2_alpha = l2_alpha,
        l2_size = l2_size,
        l2_width = l2_width,
        l2_position = l2_position,
        l2_stat = l2_stat,
        l2_method = l2_method,
        l2_se = l2_se,
        l2_bins = l2_bins,
        l2_intercept = l2_intercept,
        l2_slope = l2_slope,
        act3 = act3,
        l3_type = l3_type,
        l3_enabled = l3_enabled,
        l3_inherit = l3_inherit,
        l3_alpha = l3_alpha,
        l3_size = l3_size,
        l3_width = l3_width,
        l3_position = l3_position,
        l3_stat = l3_stat,
        l3_method = l3_method,
        l3_se = l3_se,
        l3_bins = l3_bins,
        l3_intercept = l3_intercept,
        l3_slope = l3_slope,
        act4 = act4,
        l4_type = l4_type,
        l4_enabled = l4_enabled,
        l4_inherit = l4_inherit,
        l4_alpha = l4_alpha,
        l4_size = l4_size,
        l4_width = l4_width,
        l4_position = l4_position,
        l4_stat = l4_stat,
        l4_method = l4_method,
        l4_se = l4_se,
        l4_bins = l4_bins,
        l4_intercept = l4_intercept,
        l4_slope = l4_slope,
        act5 = act5,
        l5_type = l5_type,
        l5_enabled = l5_enabled,
        l5_inherit = l5_inherit,
        l5_alpha = l5_alpha,
        l5_size = l5_size,
        l5_width = l5_width,
        l5_position = l5_position,
        l5_stat = l5_stat,
        l5_method = l5_method,
        l5_se = l5_se,
        l5_bins = l5_bins,
        l5_intercept = l5_intercept,
        l5_slope = l5_slope,
        act6 = act6,
        l6_type = l6_type,
        l6_enabled = l6_enabled,
        l6_inherit = l6_inherit,
        l6_alpha = l6_alpha,
        l6_size = l6_size,
        l6_width = l6_width,
        l6_position = l6_position,
        l6_stat = l6_stat,
        l6_method = l6_method,
        l6_se = l6_se,
        l6_bins = l6_bins,
        l6_intercept = l6_intercept,
        l6_slope = l6_slope,
        xTrans = xTrans,
        yTrans = yTrans,
        xMin = xMin,
        xMax = xMax,
        yMin = yMin,
        yMax = yMax,
        rangeMode = rangeMode,
        coordType = coordType,
        colourPalette = colourPalette,
        colourValues = colourValues,
        fillPalette = fillPalette,
        fillValues = fillValues,
        legendPosition = legendPosition,
        colourTitle = colourTitle,
        fillTitle = fillTitle,
        shapeTitle = shapeTitle,
        sizeTitle = sizeTitle,
        alphaTitle = alphaTitle,
        title = title,
        subtitle = subtitle,
        caption = caption,
        xlab = xlab,
        ylab = ylab,
        baseSize = baseSize,
        baseFamily = baseFamily,
        hideGridMajor = hideGridMajor,
        hideGridMinor = hideGridMinor,
        hideTicks = hideTicks,
        boldTitle = boldTitle,
        xTextAngle = xTextAngle,
        plotFill = plotFill,
        panelFill = panelFill,
        plotMargin = plotMargin,
        theme = theme,
        showCode = showCode)

    analysis <- layerPlotClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

